<?php session_start(); require_once 'includes/config.php'; if(empty($_SESSION['alogin'])){header('Location:index.php');exit;} $fields=['CompanyName','Address','ContactNo','EmailId','GSTIN','InvoicePrefix','PaymentMethod','BankDetails','Terms']; if(isset($_POST['save'])){$data=[];foreach($fields as $f)$data[$f]=trim($_POST[$f]??'');$sql='INSERT INTO tblinvoicesettings (id,'.implode(',',$fields).') VALUES (1,:CompanyName,:Address,:ContactNo,:EmailId,:GSTIN,:InvoicePrefix,:PaymentMethod,:BankDetails,:Terms) ON DUPLICATE KEY UPDATE CompanyName=VALUES(CompanyName),Address=VALUES(Address),ContactNo=VALUES(ContactNo),EmailId=VALUES(EmailId),GSTIN=VALUES(GSTIN),InvoicePrefix=VALUES(InvoicePrefix),PaymentMethod=VALUES(PaymentMethod),BankDetails=VALUES(BankDetails),Terms=VALUES(Terms)';$dbh->prepare($sql)->execute($data);$msg='Invoice settings saved.';} $s=$dbh->query('SELECT * FROM tblinvoicesettings WHERE id=1')->fetch(PDO::FETCH_ASSOC)?:array_fill_keys($fields,''); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice Settings</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/style.css"></head><body><?php include 'includes/header.php';?><div class="ts-main-content"><?php include 'includes/leftbar.php';?><div class="content-wrapper"><div class="container-fluid"><h2 class="page-title">Invoice Settings</h2><div class="panel panel-default"><div class="panel-heading">Company details shown on every invoice</div><div class="panel-body"><?php if(isset($msg))echo '<div class="succWrap">'.$msg.'</div>';?><form method="post" class="form-horizontal"><?php foreach(['CompanyName'=>'Business name','Address'=>'Business address','ContactNo'=>'Contact number','EmailId'=>'Email','GSTIN'=>'GSTIN','InvoicePrefix'=>'Invoice prefix','Terms'=>'Terms and conditions'] as $f=>$label){?><div class="form-group"><label class="col-sm-3 control-label"><?=$label?></label><div class="col-sm-8"><?php if(in_array($f,['Address','Terms'])){?><textarea class="form-control" name="<?=$f?>" rows="3"><?=htmlentities($s[$f])?></textarea><?php }else{?><input class="form-control" name="<?=$f?>" value="<?=htmlentities($s[$f])?>"><?php }?></div></div><?php }?><input type="hidden" name="PaymentMethod" value="Cash"><input type="hidden" name="BankDetails" value=""><button class="btn btn-primary" name="save">Save invoice settings</button></form></div></div></div></div></div></body></html>
